"""사용자 auto-generated file 하나를 그 path 의 default 로 지정하기."""

from __future__ import annotations

from dataclasses import dataclass
from typing import override

import pytest

from ai.backend.common.dto.manager.v2.auto_generated_file.request import (
    AutoGeneratedFileScopeInput,
    SwitchDefaultAutoGeneratedFileInput,
)
from ai.backend.common.dto.manager.v2.auto_generated_file.response import AutoGeneratedFileNode
from ai.backend.common.dto.manager.v2.auto_generated_file.types import AutoGeneratedFileScopeType
from ai.backend.manager.api.adapters.auto_generated_file.adapter import AutoGeneratedFileAdapter
from ai.backend.manager.data.permission.types import Permission
from ai.backend.manager.errors.permission import NotEnoughPermission
from ai.backend.manager.models.utils import ExtendedAsyncSAEngine
from ai.backend.testutils.scenario_steps import (
    Answered,
    Given,
    Held,
    Same,
    SameAs,
    Says,
    Scenario,
    Then,
    Verdict,
    When,
)
from bai_scenario.components.answers import MissingResponse, TheCallIsRefused
from bai_scenario.components.auto_generated_file import (
    A_FILE_NOT_DEFAULT,
    CONFIG_DATA,
    CONFIG_PATH,
    CONFIG_PERMISSION,
    THE_DEFAULT_FILE,
    AUserAndTheirOwnConfig,
    SomeoneWithTheirOwnConfig,
    config_files_left,
)
from bai_scenario.runner.acting import ActingAs
from bai_scenario.runner.planting import TestSeedingSession
from bai_scenario.runner.steps import run_scenario

type Laid = AUserAndTheirOwnConfig
type Answer = AutoGeneratedFileNode
type DefaultStep = Scenario[TestSeedingSession, Laid, AutoGeneratedFileAdapter, Answer]

THE_OWNER = Says("파일 주인의 id", english="the owner's id")
THE_FILE_NOT_DEFAULT = Says(
    "심어 둔 default 로 지정되지 않은 파일", english="the file seeded not set as default"
)

# 심는 순서: default 로 지정된 .vimrc, default 로 지정되지 않은 .vimrc
TWO_FILES_OF_ONE_PATH = (THE_DEFAULT_FILE, A_FILE_NOT_DEFAULT)


@dataclass(frozen=True)
class SwitchingTheDefault(When[Laid, AutoGeneratedFileAdapter, Answer]):
    """default 로 지정되지 않은 파일을 그 path 의 default 로 지정한다."""

    @override
    def operation(self) -> str:
        return "switch_default"

    @override
    def describe(self, laid: Laid) -> str:
        return Says(
            f"{laid.owner.username}이 default 로 지정되지 않은 자기 {CONFIG_PATH} auto-generated "
            "file 을 default 로 지정합니다",
            english=(
                f"{laid.owner.username} sets their {CONFIG_PATH} auto-generated file not set as "
                "default as the default"
            ),
        )

    @override
    async def call(self, adapter: AutoGeneratedFileAdapter, laid: Laid) -> Answer:
        with ActingAs(laid.owner):
            payload = await adapter.switch_default(
                SwitchDefaultAutoGeneratedFileInput(
                    scope=AutoGeneratedFileScopeInput(
                        scope_type=AutoGeneratedFileScopeType.USER, scope_id=laid.owner.id
                    ),
                    id=laid.files[1].id,
                )
            )
        return payload.auto_generated_file


@dataclass(frozen=True)
class TheFileIsNowTheDefault(Then[Laid, Answer]):
    @override
    def says(self) -> str:
        return Says(
            "지정한 파일이 default 로 지정된 채 응답으로 옵니다",
            english="the file switched to comes back set as default",
        )

    @override
    def look(self, laid: Laid, answered: Answered[Answer]) -> list[Verdict]:
        node = answered.response
        if not isinstance(node, AutoGeneratedFileNode):
            return [MissingResponse(answered.raised)]
        return [
            Held("id", node.id, SameAs(laid.files[1].id, THE_FILE_NOT_DEFAULT)),
            Held("entity_id", node.entity_id, SameAs(laid.files[1].id, THE_FILE_NOT_DEFAULT)),
            Same("scope_type", str(node.scope_type), str(AutoGeneratedFileScopeType.USER)),
            Held("scope_id", node.scope_id, SameAs(laid.owner.id, THE_OWNER)),
            Same("path", node.path, CONFIG_PATH),
            Same("permission", node.permission, CONFIG_PERMISSION),
            Same("is_default", node.is_default, True),
        ]


@dataclass(frozen=True)
class AUserSwitchesTheDefault(Scenario[TestSeedingSession, Laid, AutoGeneratedFileAdapter, Answer]):
    @override
    def summary(self) -> str:
        return "a-user-granted-update-switches-the-default-auto-generated-file-of-a-path"

    @override
    def describe(self) -> str:
        return Says(
            "UPDATE 를 받은 사용자가 같은 path 의 default 로 지정되지 않은 자기 auto-generated "
            "file 을 default 로 지정하면, 그 파일이 default 로 지정된 채 오고 이전 default 는 "
            "default 로 지정되지 않은 파일로 남습니다",
            english=(
                "when a user holding UPDATE sets their auto-generated file not set as default as "
                "the default of its path, that file comes back set as default and the previous "
                "default stays as a file not set as default"
            ),
        )

    @override
    def given(self) -> Given[TestSeedingSession, Laid]:
        return SomeoneWithTheirOwnConfig(
            permissions=(Permission.UPDATE,), files=TWO_FILES_OF_ONE_PATH
        )

    @override
    def when(self) -> When[Laid, AutoGeneratedFileAdapter, Answer]:
        return SwitchingTheDefault()

    @override
    def then(self) -> Then[Laid, Answer]:
        return TheFileIsNowTheDefault()


@dataclass(frozen=True)
class AUserGrantedNothingMayNotSwitchTheDefault(
    Scenario[TestSeedingSession, Laid, AutoGeneratedFileAdapter, Answer]
):
    @override
    def summary(self) -> str:
        return "a-user-granted-nothing-may-not-switch-the-default-auto-generated-file"

    @override
    def describe(self) -> str:
        return Says(
            "권한을 받지 않은 사용자가 자기 auto-generated file 을 default 로 지정하려 하면, 권한 "
            "부족으로 거부됩니다",
            english=(
                "a user holding no permission who tries to set their auto-generated file as the "
                "default is rejected for lack of permission"
            ),
        )

    @override
    def given(self) -> Given[TestSeedingSession, Laid]:
        return SomeoneWithTheirOwnConfig(files=TWO_FILES_OF_ONE_PATH)

    @override
    def when(self) -> When[Laid, AutoGeneratedFileAdapter, Answer]:
        return SwitchingTheDefault()

    @override
    def then(self) -> Then[Laid, Answer]:
        return TheCallIsRefused(NotEnoughPermission)


SCENARIOS: list[DefaultStep] = [
    AUserSwitchesTheDefault(),
    AUserGrantedNothingMayNotSwitchTheDefault(),
]


@pytest.mark.parametrize("scenario", SCENARIOS, ids=lambda s: s.summary())
async def test_v2_default(
    scenario: DefaultStep,
    auto_generated_file_adapter: AutoGeneratedFileAdapter,
    engine: ExtendedAsyncSAEngine,
) -> None:
    await run_scenario(scenario, auto_generated_file_adapter, engine)
    match scenario:
        case AUserSwitchesTheDefault():
            assert await config_files_left(engine) == [
                (CONFIG_PATH, CONFIG_PERMISSION, False, [(1, CONFIG_DATA)]),
                (CONFIG_PATH, CONFIG_PERMISSION, True, [(1, CONFIG_DATA)]),
            ]
        case AUserGrantedNothingMayNotSwitchTheDefault():
            assert await config_files_left(engine) == [
                (CONFIG_PATH, CONFIG_PERMISSION, False, [(1, CONFIG_DATA)]),
                (CONFIG_PATH, CONFIG_PERMISSION, True, [(1, CONFIG_DATA)]),
            ]
